head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > hammerEnabled]<br/>모바일 환경일때 Press 액션을 oncelldblclick 이벤트로 처리하기 위한 Hammer.js 라이브러리를 적용 여부를 설정합니다.",
    "validation" : [
        "true 설정 시 모바일 및 터치 환경일 때 Hammer.js 제스처 라이브러리를 적용하며, Long Press 액션 시 oncelldblclick 이벤트가 발생합니다.",
        "true 설정 시 editModeEvent='onclick' 인 경우 첫 번째 터치는 포커스만 설정하고, 동일 Cell 을 두 번째 터치해야 편집 모드에 진입합니다.",
        "false(default) 또는 미설정 시 Hammer.js 제스처 라이브러리를 적용하지 않으며, 모바일 및 터치 환경에서도 표준 터치 이벤트만으로 GridView 스크롤과 Cell 선택을 처리합니다.",
        "모바일 환경이 아니거나 dataDragDrop, dataDragDropSelf, dataDragDropOther, dataDragDropCell 속성이 모두 false 가 아니면 항상 false 로 동작합니다. (본 샘플은 dataDragDrop 계열 속성을 모두 미설정 상태로 고정)",
        "Long Press 액션 시 oncelldblclick 이벤트가 발생하기까지 누르고 있어야 하는 시간은 hammerPressTime 속성으로 설정합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // con_hammerEnabled : 공통 gdl_boolean 바인딩 (getText() 로 '' 미설정 / 'true' / 'false' 판단)
    //  - '' : 속성 자체를 추가하지 않음(기본 false)
    let vHammer = con_hammerEnabled.getText();

    // 사용법 안내 라벨 (target 생성 전 가장 먼저 생성)
    //  전제(동작 조건) : (a) 모바일/터치 환경이고 (b) dataDragDrop, dataDragDropSelf, dataDragDropOther, dataDragDropCell 이 모두 false(미설정) 여야 함.
    //  하나라도 위배되면 hammerEnabled 는 항상 false 로 동작한다. → 본 샘플은 dataDragDrop 계열 속성을 일절 설정하지 않음.
    //  hammerEnabled=true + 모바일/터치 환경에서 Cell 을 Long Press 하면 oncelldblclick 이벤트가 발생(누르는 시간은 hammerPressTime 으로 설정).
    $c.gcm.createLabel('label="전제 : (a) 모바일/터치 환경 + (b) dataDragDrop/dataDragDropSelf/dataDragDropOther/dataDragDropCell 모두 미설정(false) 일 때만 동작(본 샘플은 dataDragDrop 계열 미설정 고정). con_hammerEnabled = ' + (vHammer === '' ? '미설정(기본 false)' : vHammer) + '. true 이고 모바일/터치 환경에서 Cell 을 Long Press 하면 oncelldblclick 이벤트가 발생(누르는 시간은 hammerPressTime). editModeEvent=onclick 환경에서는 첫 터치는 포커스만, 동일 Cell 두 번째 터치에 편집모드 진입. 데스크탑에서는 항상 false 로 동작."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성 (col1=text, col2=number, col3=text, col4=number)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="col2" dataType="number"></w2:column>';
    strDlt += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col4" name="col4" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 데이터 4행 로드
    let jsonData = [
        { "col1": "행1", "col2": 100, "col3": "Aa", "col4": 10 },
        { "col1": "행2", "col2": 200, "col3": "Bb", "col4": 20 },
        { "col1": "행3", "col2": 300, "col3": "Cc", "col4": 30 },
        { "col1": "행4", "col2": 400, "col3": "Dd", "col4": 40 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정 (createCList 공통 함수)
    //  - hammerEnabled : con 선택값 ('' 미설정이면 속성 미부여 → 기본 false)
    //  - editModeEvent="onclick" : true 환경에서 '첫 터치 포커스만 / 동일 Cell 두번째 터치에 편집모드 진입' 동작을 확인하기 위한 전제
    //  - dataDragDrop 계열 속성은 전제에 따라 일절 설정하지 않음(모두 미설정 = false 유지)
    let properties = {
        dataList: "data:dlt_bind",
        editModeEvent: "onclick",
    };
    if (vHammer === 'true') {
        properties.hammerEnabled = true;
    } else if (vHammer === 'false') {
        properties.hammerEnabled = false;
    }
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';

    // target 생성 (Body 4컬럼, 단일 Row 헤더). Cell 은 편집 가능(text) 로 두어 editModeEvent 동작 확인.
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:700px;height:160px;" ev:oncelldblclick="scwin.target1_oncelldblclick">';
    strTarget += '<w2:caption style="" id="caption1" value="hammerEnabled 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="170" style="" inputType="text" id="hcol1" value="col1"></w2:column>';
    strTarget += '<w2:column width="170" style="" inputType="text" id="hcol2" value="col2"></w2:column>';
    strTarget += '<w2:column width="170" style="" inputType="text" id="hcol3" value="col3"></w2:column>';
    strTarget += '<w2:column width="170" style="" inputType="text" id="hcol4" value="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="170" style="" inputType="text" dataType="text" id="col1" dataList="col1" editType="text"></w2:column>';
    strTarget += '<w2:column width="170" style="" inputType="text" dataType="number" id="col2" dataList="col2" editType="text"></w2:column>';
    strTarget += '<w2:column width="170" style="" inputType="text" dataType="text" id="col3" dataList="col3" editType="text"></w2:column>';
    strTarget += '<w2:column width="170" style="" inputType="text" dataType="number" id="col4" dataList="col4" editType="text"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // hammerEnabled 적용값과 실제 동작값(isHammerEnabled) 출력
    //  - 적용값(options.hammerEnabled) : con 선택값에 따른 속성 적용 여부
    //  - 실제 동작값(isHammerEnabled()) : (모바일 || 터치) && hammerEnabled. 데스크탑(비터치)에서는 항상 false 로 동작.
    let applied = (typeof scwin.target1.options.hammerEnabled === 'undefined') ? '미설정(기본 false)' : scwin.target1.options.hammerEnabled;
    let effective = scwin.target1.isHammerEnabled();
    wf_body_bottom.getObj("scwin").setReturnValue("hammerEnabled 적용값(options.hammerEnabled) : " + applied);
    wf_body_bottom.getObj("scwin").setReturnValue("실제 동작값(isHammerEnabled, 모바일/터치 환경에서만 true) : " + effective);
}



// oncelldblclick : Cell 더블클릭(모바일/터치 + hammerEnabled=true 환경에서는 Long Press) 시 발생
//  - hammerEnabled=true 인 모바일/터치 환경에서 Cell 을 Long Press 하면 본 핸들러가 호출됨을 확인
scwin.target1_oncelldblclick = function (rowIndex, colIndex, value) {
    let b = wf_body_bottom.getObj("scwin");
    b.setReturnValue("oncelldblclick 발생 (Long Press → oncelldblclick) rowIndex : " + rowIndex + ", colIndex : " + colIndex + ", value : " + value);
};
